package net.officefloor.hq.app;

import java.math.BigDecimal;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * An invoice raised against a {@link Project}: a monetary amount and the id of the project it
 * belongs to. Persisted to the {@code invoices} table (Flyway V4).
 */
@Entity
@Table(name = "invoices")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "project_id")
    private Long projectId;

    private BigDecimal amount;

    /** Lifecycle stage: 'DRAFT' (the default for a new invoice), then 'SENT', then 'PAID'. */
    private String status = "DRAFT";

    /** The date the invoice went out, as an ISO date string (YYYY-MM-DD). */
    @Column(name = "issued_date")
    private String issuedDate;

    /** The date the invoice is due, as an ISO date string (YYYY-MM-DD). */
    @Column(name = "due_date")
    private String dueDate;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getProjectId() {
        return projectId;
    }

    public void setProjectId(Long projectId) {
        this.projectId = projectId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public String getIssuedDate() {
        return issuedDate;
    }

    public void setIssuedDate(String issuedDate) {
        this.issuedDate = issuedDate;
    }

    public String getDueDate() {
        return dueDate;
    }

    public void setDueDate(String dueDate) {
        this.dueDate = dueDate;
    }
}

package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

/**
 * Data access for {@link Invoice}. A Spring Data bean, injected into the OfficeFloor logic classes
 * (Spring beans are exposed to OfficeFloor by the rest-spring-boot starter).
 */
public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    /** Every invoice for one project, oldest id first — the shape a project's list renders. */
    List<Invoice> findByProjectIdOrderByIdAsc(Long projectId);

    /**
     * Every invoice across all projects with the NAME of the project it belongs to, oldest id
     * first — the shape the one all-invoices list renders.
     */
    @Query("SELECT new net.officefloor.hq.app.InvoiceView(i.id, i.projectId, p.name, i.amount, "
            + "i.status) FROM Invoice i, Project p WHERE i.projectId = p.id ORDER BY i.id ASC")
    List<InvoiceView> findAllViews();

    /**
     * Total amount still owed: the sum of every SENT-but-not-yet-paid invoice's amount across all
     * projects. Only invoices actually sent to the client count — DRAFT invoices are excluded
     * (they have not been billed yet) and PAID invoices are settled. COALESCE keeps it 0 (never
     * null) when nothing is outstanding — the dashboard's headline figure.
     */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.status = 'SENT'")
    BigDecimal sumOutstanding();
}

